class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        res = []
        take = True
        for i, row in enumerate(grid):
            seq = row if i % 2 == 0 else row[::-1]
            for v in seq:
                if take:
                    res.append(v)
                take = not take
        return res

c.cpp:
class Solution {
public:
    vector<int> zigzagTraversal(vector<vector<int>>& grid) {
        vector<int> res;
        bool take = true;
        for (int i = 0; i < grid.size(); i++) {
            const vector<int>& row = grid[i];
            int n = row.size();
            for (int k = 0; k < n; k++) {
                int v = (i % 2 == 0) ? row[k] : row[n - 1 - k];
                if (take) res.push_back(v);
                take = !take;
            }
        }
        return res;
    }
};

