class Solution {
    public List<Integer> zigzagTraversal(int[][] grid) {
        List<Integer> res = new ArrayList<>();
        boolean take = true;
        for (int i = 0; i < grid.length; i++) {
            int n = grid[i].length;
            for (int k = 0; k < n; k++) {
                int v = (i % 2 == 0) ? grid[i][k] : grid[i][n - 1 - k];
                if (take) res.add(v);
                take = !take;
            }
        }
        return res;
    }
}

